"""Compatibility against frozen outputs generated by actual historical exporters."""
import copy
import hashlib
import json
from pathlib import Path
import tempfile
from types import SimpleNamespace
import unittest

from sa_dispatch.artifacts import ArtifactStore
from sa_dispatch.bundle import import_bundle, ledger, read_bundle
from sa_dispatch.scheduler import Scheduler
from sa_dispatch.store_sqlite import SqliteStore

FIXTURES = Path(__file__).parent/'fixtures/legacy_bundles'
MANIFESTS = {
    'v1':'e6c658ead44d6a33405db54ae564b6e71af5d4575138b5cceb8a8ef239a80728',
    'v2':'57da38415cefec44b47000b5457996f1eeff6ecea9720c3ffd49e76361a2a23a',
    'v3':'eac1c23d8ce1f1bdcd1923a276053874b5944dd55779eb6f47cdf9ee5e55646d',
}


class FrozenLegacyBundleTests(unittest.TestCase):
    def restore(self, version):
        source = FIXTURES/version
        manifest_bytes = (source/'manifest.json').read_bytes()
        self.assertEqual(hashlib.sha256(manifest_bytes).hexdigest(), MANIFESTS[version])
        provenance = json.loads((FIXTURES/('provenance-'+version+'.json')).read_bytes())
        self.assertEqual(provenance['manifest_sha256'], MANIFESTS[version])
        self.assertTrue(provenance['generated_by_original_exporter'])
        self.assertFalse(provenance['current_v4_exporter_used'] if version == 'v3'
                         else provenance['current_v3_exporter_used'])
        if version == 'v1':
            self.assertEqual(provenance['source_git_commit'], '7d2f88027475888b2242b024144c98aba14ddb8e')
        elif version == 'v2':
            self.assertFalse(provenance['source_has_control_policy'])
        else:
            self.assertTrue(provenance['source_has_control_policy'])
            self.assertFalse(provenance['source_has_claude_adapter'])
            self.assertEqual(provenance['source_migration_versions'], ['0007', '0008'])
            self.assertTrue(provenance['source_unchanged'])
            self.assertEqual(provenance['source_sha256']['sa_dispatch/bundle.py'],
                             '4bdbcffb5ce6d91eb4bcb8e62c7644b21f90755092c0e53b17f9aaa7e21a8c08')
            for filename, digest in provenance['bundle_file_sha256'].items():
                self.assertEqual(hashlib.sha256((source/filename).read_bytes()).hexdigest(), digest)
        temporary = tempfile.TemporaryDirectory(prefix='sa-frozen-bundle-')
        self.addCleanup(temporary.cleanup)
        root = Path(temporary.name)
        config = SimpleNamespace(db_path=root/'ledger.sqlite3',artifact_root=root/'artifacts')
        store = SqliteStore(config.db_path,lease_ttl_seconds=60)
        manifest, _, blobs = read_bundle(source)
        report = import_bundle(config,source,store)
        after = ledger(config.db_path)
        for filename in manifest['files']:
            table = filename.removesuffix('.jsonl')
            original = [json.loads(line) for line in (source/filename).read_bytes().splitlines()]
            expected = copy.deepcopy(original)
            if table == 'schedules':
                for row in expected: row.update(enabled=0,max_slots=None)
            if table == 'schema_migrations':
                actual_by_id = {row['version']:row for row in after[table]}
                for row in expected: self.assertEqual(actual_by_id[row['version']],row)
            else:
                self.assertEqual(after[table], expected, table)
        for ref, content in blobs.items(): self.assertEqual(ArtifactStore(config.artifact_root).get(ref),content)
        self.assertEqual((source/'manifest.json').read_bytes(),manifest_bytes)
        return store, report

    def test_original_v1_three_task_fixture_imports_without_fabricated_extensions(self):
        store, report = self.restore('v1')
        self.assertEqual(report['tasks'],3)
        self.assertEqual(store.snapshot()['reconciliations'],[])
        self.assertEqual(store.snapshot()['control_budgets'],[])
        self.assertEqual(store.snapshot()['devices'],[])

    def test_original_v3_selftest_retains_rows_blobs_and_0008_history(self):
        store, report = self.restore('v3')
        snapshot = store.snapshot()
        self.assertEqual(report['schema'], 'sa_dispatch.bundle.v3')
        self.assertEqual(report['tasks'], 3)
        self.assertEqual(report['artifacts'], 3)
        self.assertEqual(len(snapshot['events']), 9)
        self.assertEqual(len(snapshot['evidence']), 3)
        self.assertEqual({row['status'] for row in snapshot['tasks']}, {'succeeded'})
        self.assertEqual(snapshot['claude_attempts'], [])
        self.assertEqual(snapshot['devices'], [])
        self.assertGreaterEqual({row['version'] for row in snapshot['schema_migrations']},
                                {'0007', '0008', '0009'})
        self.assertTrue(report['target_migration_metadata_retained'])


if __name__ == '__main__': unittest.main()
